import { formatCurrency, ICurrencySettings } from '@game-studio/utilities';
import { Component, Prop, Vue, Watch } from 'vue-property-decorator';
import { IWalletOptions, IWalletPopupTranslations } from '../../types';
import { VueSliderExtension } from '../../vue-slider-extension';

@Component({
    components: { VueSlider: VueSliderExtension },
})
export default class WalletPopup extends Vue {
    public $refs: Vue['$refs'] & {
        plusButton: HTMLDivElement;
        minusButton: HTMLDivElement;
        slider: HTMLDivElement;
    };

    public disabled: boolean = false;

    @Prop()
    public currentBalance: number;

    @Prop({
        type: Number,
        default: 1
    })
    public viewportScale: number;

    @Prop()
    private readonly currencySettings: ICurrencySettings;

    @Prop()
    private readonly translations: IWalletPopupTranslations;

    @Prop()
    private isFreePlay: boolean;

    @Prop()
    private region: string;

    @Prop()
    private requestInProgress: boolean;

    @Prop()
    private initialSliderValue: number;

    private readonly options: IWalletOptions = {
        tooltip: 'none',
        height: '16px',
        width: '80%',
        dotSize: 30,
        duration: 0.1,
    };

    private sliderValue: number = 50;

    private previousSliderValue: number = 0;
    private window: Window;

    public setSliderValue(sliderValue: number): void {
        this.sliderValue = sliderValue;
    }

    public created(): void {
        this.sliderValue = this.initialSliderValue;
        this.checkButtonDisabledStatus();
    }

    public mounted(): void {
        this.window = window;

        // Set the slider buttons based on initial balance
        this.updateSliderButtons();
    }

    @Watch('sliderValue')
    private onSliderValueChanged(_newSliderValue: number): void {
        this.checkButtonDisabledStatus();
        this.updateSliderButtons();
    }

    private get freePlayIconUrl(): string {
        switch (this.region) {
            case 'it-it':
                return `url(${require('../../assets/icons/free-play-teal-IT.png')})`;
            case 'es-es':
                return `url(${require('../../assets/icons/free-play-teal-ES.png')})`;
            default:
                return `url(${require('../../assets/icons/free-play.png')})`;
        }
    }

    private get currentBalanceFormatted(): string {
        return this.isFreePlay ? this.currentBalance.toString()
            : formatCurrency(this.currentBalance, this.currencySettings, false);
    }

    private get isMinusDisabled(): boolean {
        return this.sliderValue <= 0;
    }

    private get isPlusDisabled(): boolean {
        return this.sliderValue >= 100;
    }

    private get selectedBalanceFormatted(): string {
        return formatCurrency(
            Math.round((this.cappedBalance / 100) * this.sliderValue),
            this.currencySettings,
            false
        );
    }

    private get cappedBalance(): number {
        const balanceCap: number = 100000;
        return this.currentBalance > balanceCap ? balanceCap : this.currentBalance;
    }

    private sliderChange(): void {
        this.checkButtonDisabledStatus();
        this.updateSliderButtons();
    }

    private checkButtonDisabledStatus(): void {
        this.disabled = this.sliderValue === 0;
    }

    private submitSelected(): void {
        this.emitBalanceConfirmation(
            Math.round((this.cappedBalance / 100) * this.sliderValue)
        );
    }

    private submitMax(): void {
        this.emitBalanceConfirmation(this.cappedBalance);
    }

    private closeForm(): void {
        this.$emit('close-popup');
    }

    private updateSliderValue(incrementValue: number): void {
        if ((this.sliderValue + incrementValue) < 0) {
            this.setSliderValue(0);
        } else if ((this.sliderValue + incrementValue) > 100) {
            this.setSliderValue(100);
        } else {
            this.sliderValue += incrementValue;
        }
    }

    private updateSliderButtons(): void {
        if (this.isFreePlay) return;

        const plusButton = this.$refs.plusButton;
        const minusButton = this.$refs.minusButton;

        this.sliderValue < 100 ? plusButton.classList.remove('disabled') : plusButton.classList.add('disabled');
        this.sliderValue > 0 ? minusButton.classList.remove('disabled') : minusButton.classList.add('disabled');

    }

    private emitBalanceConfirmation(balance: number): void {
        if (!this.requestInProgress) {
            this.$emit('balance-confirmation', balance);
        }
    }
}